WITH inner_cte1 AS ( SELECT ssc.DEPARTMENT_CODE, ssc.DEPARTMENT_NAME, VARIANCE(sos.TOTAL_UNITS) AS total_units_variance, AVG(sos.NUM_ENROLLED_STUDENTS) AS avg_enrolled_students FROM SIS_SUBJECT_CODE ssc JOIN SIS_COURSE_DESCRIPTION scd ON ssc.COURSE_NUMBER = scd.COURSE JOIN SUBJECT_OFFERED_SUMMARY sos ON scd.COURSE = sos.COURSE_NUMBER WHERE sos.NUM_ENROLLED_STUDENTS > 0 AND scd.IS_DEGREE_GRANTING = 'Y' GROUP BY ssc.DEPARTMENT_CODE, ssc.DEPARTMENT_NAME ), dept_stats AS ( SELECT inner_cte1.DEPARTMENT_CODE, inner_cte1.DEPARTMENT_NAME, inner_cte1.total_units_variance, inner_cte1.avg_enrolled_students, CASE WHEN inner_cte1.avg_enrolled_students > overall.avg_all_enrolled * 1.2 THEN 'HIGH_ENROLLMENT' WHEN inner_cte1.avg_enrolled_students < overall.avg_all_enrolled * 0.8 THEN 'LOW_ENROLLMENT' ELSE 'AVERAGE' END AS enrollment_category FROM inner_cte1 CROSS JOIN ( SELECT AVG(sos.NUM_ENROLLED_STUDENTS) AS avg_all_enrolled FROM SIS_COURSE_DESCRIPTION scd JOIN SUBJECT_OFFERED_SUMMARY sos ON scd.COURSE = sos.COURSE_NUMBER WHERE sos.NUM_ENROLLED_STUDENTS > 0 AND scd.IS_DEGREE_GRANTING = 'Y' ) overall ), inner_cte2 AS ( SELECT l.LIBRARY_COURSE_INSTRUCTOR_KEY, l.LIBRARY_RESERVE_CATALOG_KEY, l.TERM_CODE, l.SUBJECT_ID, t.TIP_MATERIAL_KEY, t.TIP_MATERIAL_STATUS_KEY, t.ISBN, s.SUBJECT_TITLE, MIN(t.TIP_MATERIAL_STATUS_KEY) OVER ( ORDER BY s.NUM_ENROLLED_STUDENTS ROWS BETWEEN 3 PRECEDING AND 1 FOLLOWING ) AS window_column, s.TIP_SUBJECT_OFFERED_KEY FROM LIBRARY_RESERVE_MATRL_DETAIL l JOIN TIP_DETAIL t ON l.SUBJECT_ID = t.SUBJECT_ID JOIN TIP_SUBJECT_OFFERED s ON t.SUBJECT_ID = s.SUBJECT_ID WHERE l.LIBRARY_MATERIAL_STATUS_KEY = 'U' ) SELECT ds.DEPARTMENT_CODE, ds.DEPARTMENT_NAME, ds.total_units_variance, ds.avg_enrolled_students, ds.enrollment_category, ic2.LIBRARY_COURSE_INSTRUCTOR_KEY, ic2.LIBRARY_RESERVE_CATALOG_KEY, ic2.TERM_CODE, ic2.SUBJECT_ID, ic2.TIP_MATERIAL_KEY, ic2.TIP_MATERIAL_STATUS_KEY, ic2.ISBN, ic2.SUBJECT_TITLE, ic2.window_column, tso.RESPONSIBLE_FACULTY_NAME, tso.OFFER_DEPT_NAME FROM dept_stats ds JOIN SUBJECT_OFFERED_SUMMARY sos ON ds.DEPARTMENT_CODE = sos.OFFER_DEPT_CODE JOIN inner_cte2 ic2 ON sos.SUBJECT_ID = ic2.SUBJECT_ID AND sos.TERM_CODE = ic2.TERM_CODE JOIN TIP_SUBJECT_OFFERED tso ON ic2.TIP_SUBJECT_OFFERED_KEY = tso.TIP_SUBJECT_OFFERED_KEY ORDER BY ds.total_units_variance DESC, ds.DEPARTMENT_NAME, ic2.LIBRARY_COURSE_INSTRUCTOR_KEY;